39	var ErrTableFileNotFound = errors.New("table file not found")
40	
41	type fileTableReader struct {
42		tableReader
43		h hash.Hash
44	}
45	
46	var _ chunkSource = &fileTableReader{}
47	
48	const (
49		fileBlockSize = 1 << 12
50	)
51	
52	func tableFileExists(ctx context.Context, dir string, h hash.Hash) (bool, error) {
53		path := filepath.Join(dir, h.String())
54		_, err := os.Stat(path)
55	
56		if os.IsNotExist(err) {
57			return false, nil
58		}
59	
60		return err == nil, err
61	}
62	
63	func archiveFileExists(ctx context.Context, dir string, name string) (bool, error) {
64		if !strings.HasSuffix(name, ArchiveFileSuffix) {
65			_, ok := hash.MaybeParse(name)
66			if !ok {
67				return false, errors.New(fmt.Sprintf("invalid archive file name: %s", name))
68			}
69	
70			name = fmt.Sprintf("%s%s", name, ArchiveFileSuffix)
71		}
72	
73		path := filepath.Join(dir, name)
74		_, err := os.Stat(path)
75	
76		if os.IsNotExist(err) {
77			return false, nil
78		}
79	
80		return err == nil, err
81	}
82	
83	func newFileTableReader(ctx context.Context, dir string, h hash.Hash, chunkCount uint32, q MemoryQuotaProvider, mmapArchiveIndexes bool, stats *Stats) (cs chunkSource, err error) {
84		// we either have a table file or an archive file
85		tfExists, err := tableFileExists(ctx, dir, h)
86		if err != nil {
87			return nil, err
88		} else if tfExists {
89			return nomsFileTableReader(ctx, filepath.Join(dir, h.String()), h, chunkCount, q)
90		}
91	
92		afExists, err := archiveFileExists(ctx, dir, h.String())
93		if err != nil {
94			return nil, err
95		} else if afExists {
96			return newArchiveChunkSource(ctx, dir, h, chunkCount, q, mmapArchiveIndexes, stats)
97		}
98		return nil, fmt.Errorf("error opening table file: %w: %s/%s", ErrTableFileNotFound, dir, h.String())
99	}
100	
101	func newFileReaderAt(path string, mmapArchiveIndexes bool) (*fileReaderAt, error) {
102		f, err := os.Open(path)
103		if err != nil {
104			return nil, err
105		}
106		fi, err := f.Stat()
107		if err != nil {
108			return nil, err
109		}
110		if fi.Size() < 0 {
111			// Size returns the number of bytes for regular files and is system dependent for others (Some of which can be negative).
112			return nil, fmt.Errorf("%s has invalid size: %d", path, fi.Size())
113		}
114		cnt := new(int32)
115		*cnt = 1
116		return &fileReaderAt{f, cnt, path, fi.Size(), mmapArchiveIndexes}, nil
117	}
118	
119	func nomsFileTableReader(ctx context.Context, path string, h hash.Hash, chunkCount uint32, q MemoryQuotaProvider) (cs chunkSource, err error) {
120		// noms files never support mmapped indexes
121		fra, err := newFileReaderAt(path, false)
122		if err != nil {
123			return nil, err
124		}
125	
126		idxSz := int64(indexSize(chunkCount) + footerSize)
127		indexOffset := fra.sz - idxSz
128		r := io.NewSectionReader(fra.f, indexOffset, idxSz)
129		if int64(int(idxSz)) != idxSz {
130			err = fmt.Errorf("table file %s is too large to read on this platform. index size %d > max int.", path, idxSz)
131			return
132		}
133	
134		var b []byte
135		b, err = q.AcquireQuotaByteSlice(ctx, int(idxSz))
136		if err != nil {
137			fra.Close()
138			return
139		}
140	
141		_, err = io.ReadFull(r, b)
142		if err != nil {
143			q.ReleaseQuotaBytes(len(b))
144			fra.Close()
145			return
146		}
147	
148		index, err := parseTableIndex(ctx, b, q)
149		if err != nil {
150			q.ReleaseQuotaBytes(len(b))
151			fra.Close()
152			return
153		}
154	
155		if chunkCount != index.chunkCount() {
156			index.Close()
157			fra.Close()
158			return nil, errors.New("unexpected chunk count")
159		}
160	
161		tr, err := newTableReader(ctx, index, fra, fileBlockSize)
162		if err != nil {
163			index.Close()
164			fra.Close()
165			return nil, err
166		}
167		return &fileTableReader{
168			tr,
169			h,
170		}, nil
171	}
172	
173	func (ftr *fileTableReader) hash() hash.Hash {
174		return ftr.h
175	}
176	
177	func (ftr *fileTableReader) suffix() string {
178		return ""
179	}
180	
181	func (ftr *fileTableReader) Close() error {
182		return ftr.tableReader.close()
183	}
184	
185	func (ftr *fileTableReader) clone() (chunkSource, error) {
186		tr, err := ftr.tableReader.clone()
187		if err != nil {
188			return &fileTableReader{}, err
189		}
190		return &fileTableReader{tr, ftr.h}, nil
191	}
192	
193	type fileReaderAt struct {
194		f *os.File
195		// refcnt, clone() increments and Close() decrements. The *os.File is closed when it reaches 0.
196		cnt         *int32
197		path        string
198		sz          int64
199		mmapIndexes bool // If possible, the file reader will mmap the file for reading index data.
200	}
201	
202	func (fra *fileReaderAt) clone() (tableReaderAt, error) {
203		if !dynassert.Assert(atomic.AddInt32(fra.cnt, 1) > 1, "attempt to clone a closed fileReaderAt") {
204			// Restore previous refcnt, despite being in a weird state...
205			atomic.AddInt32(fra.cnt, -1)
206			return newFileReaderAt(fra.path, fra.mmapIndexes)
207		}
208		return &fileReaderAt{
209			f:           fra.f,
210			path:        fra.path,
211			sz:          fra.sz,
212			cnt:         fra.cnt,
213			mmapIndexes: fra.mmapIndexes,
214		}, nil
215	}
216	
217	func (fra *fileReaderAt) Close() error {
218		cnt := atomic.AddInt32(fra.cnt, -1)
219		dynassert.Assert(cnt >= 0, "invalid cnt on fileReaderAt")
220		if cnt == 0 {
221			return fra.f.Close()
222		}
223		return nil
224	}
225	
226	func (fra *fileReaderAt) Reader(ctx context.Context) (io.ReadCloser, error) {
227		return os.Open(fra.path)
228	}
229	
230	func (fra *fileReaderAt) ReadAtWithStats(ctx context.Context, p []byte, off int64, stats *Stats) (n int, err error) {
231		t1 := time.Now()
232		defer func() {
233			stats.FileBytesPerRead.Sample(uint64(len(p)))
234			stats.FileReadLatency.SampleTimeSince(t1)
235		}()
236		return fra.f.ReadAt(p, off)
237	}
238	
239	func newTableFileMetadata(path string, chunkCount uint32) (*TableFileMetadata, error) {
240		// table files can never have mmapped indexes
241		fra, err := newFileReaderAt(path, false)
242		if err != nil {
243			return nil, err
244		}
245	
246		idxSz := int64(indexSize(chunkCount) + footerSize)
247		indexOffset := fra.sz - idxSz
248	
249		return &TableFileMetadata{
250			snappyChunkCount: int(chunkCount),
251			snappyBytes:      uint64(indexOffset),
252		}, nil
253	}
