47	func newFSTablePersister(dir string, q MemoryQuotaProvider, mmapArchiveIndexes bool) tablePersister {
48		return &fsTablePersister{q, nil, make(map[string]struct{}), dir, sync.Mutex{}, mmapArchiveIndexes}
49	}
