51	type fsTablePersister struct {
52		q MemoryQuotaProvider
53		// While we are running PruneTableFiles, any newly created table files are
54		// added to this map. The file delete loop will never delete anything which
55		// appears in this map. Files should be added to this map before they are
56		// written.
57		toKeep map[string]struct{}
58		// Any temp files we are currently writing are always present in this map.
59		// The logic should be taken before we generate the new temp file, and the
60		// new temp file should be added to this map. Care should be taken to always
61		// remove the entry from this map when we are done processing the temp file
62		// or else this map will grow without bound.
63		curTmps map[string]struct{}
64		dir     string
65		// Protects the toKeep and curTmps maps.
66		removeMu           sync.Mutex
67		mmapArchiveIndexes bool
68	}
