54	func newAWSArchiveChunkSource(ctx context.Context,
55		s3 *s3ObjectReader,
56		al awsLimits,
57		name string,
58		chunkCount uint32,
59		q MemoryQuotaProvider,
60		stats *Stats) (cs chunkSource, err error) {
61	
62		footer, err := q.AcquireQuotaByteSlice(ctx, int(archiveFooterSize))
63		if err != nil {
64			return emptyChunkSource{}, err
65		}
66		defer q.ReleaseQuotaBytes(int(archiveFooterSize))
67		// sz is what we are really after here, but we'll use the bytes to construct the footer to avoid another call.
68		_, sz, err := s3.readS3ObjectFromEnd(ctx, name, footer, stats)
69		if err != nil {
70			return emptyChunkSource{}, err
71		}
72	
73		id := strings.TrimSuffix(filepath.Base(name), ArchiveFileSuffix)
74		hashId, ok := hash.MaybeParse(id)
75		if !ok {
76			return emptyChunkSource{}, fmt.Errorf("invalid archive file path: %s", name)
77		}
78	
79		aRdr, err := newArchiveReaderFromFooter(ctx, &s3TableReaderAt{s3, name}, hashId, sz, footer, q, stats)
80		if err != nil {
81			return emptyChunkSource{}, err
82		}
83		return &archiveChunkSource{aRdr, ""}, nil
84	}
