func tableFileExists(ctx context.Context, dir string, h hash.Hash) (bool, error) {
	path := filepath.Join(dir, h.String())
	_, err := os.Stat(path)

	if os.IsNotExist(err) {
		return false, nil
	}

	return err == nil, err
}

func archiveFileExists(ctx context.Context, dir string, name string) (bool, error) {
	if !strings.HasSuffix(name, ArchiveFileSuffix) {
		_, ok := hash.MaybeParse(name)
		if !ok {
			return false, errors.New(fmt.Sprintf("invalid archive file name: %s", name))
		}

		name = fmt.Sprintf("%s%s", name, ArchiveFileSuffix)
	}

	path := filepath.Join(dir, name)
	_, err := os.Stat(path)

	if os.IsNotExist(err) {
		return false, nil
	}

	return err == nil, err
}

func newFileTableReader(ctx context.Context, dir string, h hash.Hash, chunkCount uint32, q MemoryQuotaProvider, mmapArchiveIndexes bool, refs refCounter, stats *Stats) (cs chunkSource, err error) {
	// we either have a table file or an archive file
	tfExists, err := tableFileExists(ctx, dir, h)
	if err != nil {
		return nil, err
	} else if tfExists {
		return nomsFileTableReader(ctx, filepath.Join(dir, h.String()), h, chunkCount, refs, q)
	}

	afExists, err := archiveFileExists(ctx, dir, h.String())
	if err != nil {
		return nil, err
	} else if afExists {
		return newArchiveChunkSource(ctx, dir, h, chunkCount, q, mmapArchiveIndexes, refs, stats)
	}
	return nil, fmt.Errorf("error opening table file: %w: %s/%s", ErrTableFileNotFound, dir, h.String())
}

func newFileReaderAt(path string, mmapArchiveIndexes bool) (*fileReaderAt, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	fi, err := f.Stat()
	if err != nil {
		return nil, err
	}
	if fi.Size() < 0 {
		// Size returns the number of bytes for regular files and is system dependent for others (Some of which can be negative).
		return nil, fmt.Errorf("%s has invalid size: %d", path, fi.Size())
	}
	cnt := new(int32)
	*cnt = 1
	return &fileReaderAt{f, cnt, path, fi.Size(), mmapArchiveIndexes}, nil
}

func nomsFileTableReader(ctx context.Context, path string, h hash.Hash, chunkCount uint32, refs refCounter, q MemoryQuotaProvider) (cs chunkSource, err error) {
	// noms files never support mmapped indexes
	fra, err := newFileReaderAt(path, false)
	if err != nil {
		return nil, err
	}

	idxSz := int64(indexSize(chunkCount) + footerSize)
	indexOffset := fra.sz - idxSz
	r := io.NewSectionReader(fra.f, indexOffset, idxSz)
	if int64(int(idxSz)) != idxSz {
		err = fmt.Errorf("table file %s is too large to read on this platform. index size %d > max int.", path, idxSz)
		return
	}

	var b []byte
	b, err = q.AcquireQuotaByteSlice(ctx, int(idxSz))
	if err != nil {
		fra.Close()
		return
	}

	_, err = io.ReadFull(r, b)
	if err != nil {
		q.ReleaseQuotaBytes(len(b))
		fra.Close()
		return
	}

	index, err := parseTableIndex(ctx, b, q)
	if err != nil {
		q.ReleaseQuotaBytes(len(b))
		fra.Close()
		return
	}

	if chunkCount != index.chunkCount() {
		index.Close()
		fra.Close()
		return nil, errors.New("unexpected chunk count")
	}

	tr, err := newTableReader(ctx, index, fra, fileBlockSize)
	if err != nil {
		index.Close()
		fra.Close()
		return nil, err
	}
	if refs != nil {
		refs.addRef()
	}
	return &fileTableReader{
		tr,
		h,
		refs,
	}, nil
}

