// refCounter tracks reference counts on open table files. Implementations allow
// the persister to know when a file is still in use so that it is not deleted
// while there are outstanding readers.
type refCounter interface {
	addRef()
	decRef()
}

// noopRefCounter is a refCounter that does nothing. It is used when reference
// counting is not needed, such as in tests or one-off reads.
type noopRefCounter struct{}

func (noopRefCounter) addRef() {}
func (noopRefCounter) decRef() {}

var _ refCounter = noopRefCounter{}

// fsPersisterRefCounter is a refCounter bound to a single table file managed by
// an fsTablePersister. It increments and decrements the persister's open-file
// reference count for the file's path.
type fsPersisterRefCounter struct {
	ftp  *fsTablePersister
	path string
}

func (rc fsPersisterRefCounter) addRef() {
	rc.ftp.openMu.Lock()
	defer rc.ftp.openMu.Unlock()
	rc.ftp.openFiles[rc.path]++
}

func (rc fsPersisterRefCounter) decRef() {
	rc.ftp.openMu.Lock()
	defer rc.ftp.openMu.Unlock()
	if n, ok := rc.ftp.openFiles[rc.path]; ok {
		if n <= 1 {
			delete(rc.ftp.openFiles, rc.path)
		} else {
			rc.ftp.openFiles[rc.path] = n - 1
		}
	}
}

